<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>راستا — هر قدم، نزدیک‌تر به هدف</title>@vite(['resources/css/app.css','resources/js/app.js'])</head>
<body><div x-data="workspace" class="app-shell" x-cloak>
<div class="sidebar-backdrop" x-show="sidebar" @click="sidebar=false"></div>
<aside class="sidebar" :class="{'is-open':sidebar}">
 <a href="/dashboard" @click.prevent="go('dashboard')" class="brand"><span class="brand-symbol"><span></span><span></span><span></span></span><strong>راستا<span>فضای کار تیمی</span></strong></a>
 <div class="workspace-switch"><span class="workspace-mark">ا</span><div><strong>استودیو اُجا</strong><small>فضای کار شما</small></div><span x-html="$icon('ChevronDown')"></span></div>
 <button class="button primary add-global" @click="openTask()"><span x-html="$icon('Plus')"></span>افزودن تسک<span class="shortcut">＋</span></button>
 <nav aria-label="ناوبری اصلی"><a href="/dashboard" @click.prevent="go('dashboard')" :class="{'active':page==='dashboard'}"><span x-html="$icon('House')"></span>خانه</a><a href="/tasks" @click.prevent="go('tasks')" :class="{'active':page==='tasks'}"><span x-html="$icon('CheckCheck')"></span>تسک‌های من<span class="nav-count" x-text="fa(myTasks.filter(t=>!t.completed_at).length)"></span></a><a href="/projects" @click.prevent="go('projects')" :class="{'active':page==='projects'}"><span x-html="$icon('FolderClosed')"></span>پروژه‌ها<span class="nav-count" x-text="fa(projects.length)"></span></a></nav>
 <div class="sidebar-projects"><div class="eyebrow">پروژه‌های شما <button class="icon-btn" @click="openProject()" aria-label="پروژه جدید" x-html="$icon('Plus')"></button></div><template x-for="p in projects.slice(0,4)" :key="p.id"><button class="project-shortcut" @click="go('projects',p.id)"><i :style="`background:${p.color}`"></i><span x-text="p.name"></span></button></template></div>
 <div class="sidebar-bottom"><div class="tip-card"><span class="tip-symbol" x-html="$icon('Target')"></span><strong>قدم‌های کوچک، هدف‌های بزرگ</strong><p>هر تسک تکمیل‌شده، یک قدم به مقصد نزدیک‌تر است.</p></div><nav><a href="/labels" @click.prevent="go('labels')" :class="{'active':page==='labels'}"><span x-html="$icon('Tags')"></span>برچسب‌ها</a><a href="/settings" @click.prevent="go('settings')" :class="{'active':page==='settings'}"><span x-html="$icon('Settings')"></span>تنظیمات</a></nav><button class="user-account" @click="go('settings')"><span class="avatar" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span><span><strong x-text="user.name"></strong><small>حساب کاربری</small></span><span x-html="$icon('ChevronLeft')"></span></button></div>
</aside>
<div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" @click="sidebar=!sidebar" aria-label="باز کردن منو" x-html="$icon('Menu')"></button><span>فضای کار</span><span x-html="$icon('ChevronLeft')"></span><strong x-text="({dashboard:'خانه',projects:'پروژه‌ها',tasks:'تسک‌های من',labels:'برچسب‌ها',settings:'تنظیمات'})[page]"></strong><template x-if="currentProject"><span class="crumb-project"><span x-html="$icon('ChevronLeft')"></span><span x-text="currentProject.name"></span></span></template></div><div class="top-actions"><div class="search-wrap" @click.outside="searchOpen=false"><span x-html="$icon('Search')"></span><input x-ref="search" x-model="query" @focus="searchOpen=true" placeholder="جست‌وجو در فضای کار..." aria-label="جست‌وجو"><kbd>⌘ K</kbd><div class="search-results" x-show="searchOpen&&query"><template x-for="(r,i) in searchResults" :key="i"><button @click="r.task?openTask(r.task):go('projects',r.project);searchOpen=false"><span x-text="r.title"></span><small x-text="r.type"></small></button></template><p x-show="!searchResults.length">نتیجه‌ای پیدا نشد.</p></div></div><span class="top-divider"></span><div class="notification-wrap" @click.outside="notificationsOpen=false"><button class="icon-btn notification-button" @click="notificationsOpen=!notificationsOpen" aria-label="اعلان‌ها"><span x-html="$icon('Bell')"></span><i x-show="unread"></i></button><div class="notification-panel" x-show="notificationsOpen"><div class="section-heading"><strong>اعلان‌ها</strong><button class="text-button" @click="readNotices()">خواندن همه</button></div><template x-for="n in notices" :key="n.id"><button :class="{'unread':!n.read_at}" @click="openTask(tasks.find(t=>t.id===n.task_id));notificationsOpen=false"><span x-text="n.body"></span><small x-text="new Date(n.created_at).toLocaleString('fa-IR')"></small></button></template><p class="muted" x-show="!notices.length">همه چیز به‌روز است.</p><div class="notice-upcoming" x-show="upcoming.length"><strong>مهلت‌های نزدیک</strong><template x-for="t in upcoming.slice(0,3)" :key="t.id"><button @click="openTask(t);notificationsOpen=false"><span x-text="t.title"></span><small x-text="date(t.due_date)"></small></button></template></div></div></div><button class="avatar small" @click="go('settings')" :style="`background:${color(user.id)}`" x-text="initials(user.name)" aria-label="حساب کاربری"></button></div></header>
<main class="content">@include('partials.live-test-notice')<div x-show="loading" class="skeleton-wrap"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div x-show="loadError" class="error-banner"><span x-text="loadError"></span><button class="button" @click="refresh()">تلاش دوباره</button></div><div x-show="!loading&&!loadError">
@include('partials.dashboard')
@include('partials.projects')
@include('partials.tasks')
@include('partials.labels-settings')
</div></main><footer class="app-footer"><span class="status-dot"></span>فضایی برای تمرکز، مسیری برای رسیدن.<span>ساخته‌شده برای کار تیمی</span></footer></div>
@include('partials.modals')
<div class="confirm-backdrop" x-show="confirmBox" x-cloak @keydown.escape.stop="confirmBox=null"><section class="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title" x-text="confirmBox?.title"></h2><p x-text="confirmBox?.body"></p><div class="button-row"><button class="button danger" @click="confirm()" x-text="confirmBox?.label"></button><button class="button" @click="confirmBox=null">انصراف</button></div></section></div>
<div class="toast" x-show="toast" x-transition :class="{'toast-error':toastError}" role="status"><span x-html="$icon(toastError?'X':'CheckCircle2')"></span><span x-text="toast"></span><button class="icon-btn" @click="toast=''" aria-label="بستن پیام" x-html="$icon('X')"></button></div>
</div></body></html>
